from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django.conf import settings
from .models import ClusterNodeDiagnostic

class ClusterNodeMetricsView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, node_id):
        if not request.user.is_staff or not request.user.has_perm('infra.view_cluster_telemetry'):
            return Response({'error': 'Infrastructure staff privileges required'}, status=status.HTTP_403_FORBIDDEN)

        node = ClusterNodeDiagnostic.objects.filter(node_id=node_id, cluster__managed_by=request.user).first()
        if not node:
            return Response({'error': 'Node not found or not in authorized cluster'}, status=status.HTTP_404_NOT_FOUND)

        data = {
            'node_id': node_id,
            'cluster': node.cluster_name,
            'active_tenant_ids': node.active_tenant_ids,
            'internal_ip': node.internal_ip
        }
        response = Response(data)
        origin = request.headers.get('Origin')
        if origin in settings.CORS_ALLOWED_ORIGINS:
            response['Access-Control-Allow-Origin'] = origin
            response['Access-Control-Allow-Credentials'] = 'true'
        return response
